esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// pgbouncer_pools_client_maxwait_seconds is a gauge: the longest a client has currently
// been waiting for a server connection in this pool. AVG(AVG_OVER_TIME()) matches the
// dashboard panel; the peak and the waiting-client count are carried as context.
| STATS
    `Avg Client Wait (s)` = AVG(AVG_OVER_TIME(pgbouncer_pools_client_maxwait_seconds)),
    `Peak Client Wait (s)` = MAX(MAX_OVER_TIME(pgbouncer_pools_client_maxwait_seconds)),
    `Clients Waiting` = MAX(MAX_OVER_TIME(pgbouncer_pools_client_waiting_connections))
  BY resource.attributes.supabase_project_ref, attributes.database, attributes.user
// One second of average wait across the window means clients are blocked on the pool,
// not on the database. Lower to 0.5 for latency-sensitive workloads.
| WHERE `Avg Client Wait (s)` > 1
// One row per pool, so the alert instance key includes database and user.
| EVAL alert_instance = CONCAT(resource.attributes.supabase_project_ref, " / ", attributes.database, " / ", attributes.user)
| SORT `Avg Client Wait (s)` DESC
